def v_id = holder.getNodeValue("//*:verladeauftrag_id")
def s_id = holder.getNodeValue("//*:verladestrasse_id")
log.info("PDAAnmeldung Request entered wit v_id: " + v_id + ", s_id: " + s_id)
// check values (first three for nightly buil)
if(v_id == '100'){
	return "TechnicalError"
}else if (v_id == '200'){
	return "ApplicationError"
}else if (v_id == '300'){
	return "EmptyResponse"
}else{
	// read all values from XML and transfer to properties
	String path = "//*:LKWVerladeAuftragNeu"
	nodes = holder.getDomNodes("//*:LKWVerladeAuftragNeu/*")
	for (node in nodes){
		nsAndName = node.getNodeName()
		name = nsAndName.substring(4) //assuming ns is "log:"
		value = holder.getNodeValue("//*:LKWVerladeAuftragNeu/" + nsAndName)
		log.info ("name: " + name + ", value: " + value)
		mockOperation.getMockService().setPropertyValue(name, value)
	}
	return "NoError"
}

