import java.io.File;
import java.io.FileInputStream;
import java.util.Properties;

import javax.mail.Message;
import javax.mail.Session;
import javax.mail.Transport;
import javax.mail.internet.InternetAddress;
import javax.mail.internet.MimeMessage;

static final String SIM_EXEC_DIRECTORY = ".";
static final String PROPERTY_DIRECTORY = "build/dist/etc/soapui/";
static final String PROPERTY_FILE_NAME = "soapui.properties";
static final String ENABLED_PROPERTY   = "mockup.email.enabled";
static final String RECIPIENT_PROPERTY = "mockup.email.recipient";
static final String SMTP_HOST_PROPERTY = "mockup.email.smtp.host";
static final String DEFAULT_SMTP_HOST  = "smtp-dev.adnovum.ch";

def groovyUtils = new com.eviware.soapui.support.GroovyUtils(context)
def xmlHolder   = groovyUtils.getXmlHolder(mockRequest.requestContent)
def phoneNumber = xmlHolder.getNodeValue("//*:argsNumber")
def smsText     = xmlHolder.getNodeValue("//*:argsText")

log.info("Phone number: " + phoneNumber)
log.info("SMS text    : " + smsText)

boolean success = false;
try {
	// Get name of user who is running the application.
	Properties systemProperties = System.getProperties();
	String userName = systemProperties.getProperty("user.name");

	// Get configurable properties.
	String enabled = null;
	String smtpHost = null;
	String recipient = null;
	File propertyDir = new File(SIM_EXEC_DIRECTORY, PROPERTY_DIRECTORY);
	File propertyFile = new File(propertyDir, PROPERTY_FILE_NAME);
	try {
		Properties properties = new Properties();
		properties.load(new FileInputStream(propertyFile));
		enabled = properties.getProperty(ENABLED_PROPERTY);
		smtpHost = properties.getProperty(SMTP_HOST_PROPERTY);
		recipient = properties.getProperty(RECIPIENT_PROPERTY);
	}
	catch (Exception e) {
		log.error("Could not load properties file " + propertyFile.getAbsolutePath(), e);
	}
	if (smtpHost == null || smtpHost.equals("")) {
		smtpHost = DEFAULT_SMTP_HOST;
	}
	if (recipient == null || recipient.equals("")) {
		recipient = userName + "@adnovum.ch";
	}

	// If enabled, send e-mail confirmation of SMS.
	if (enabled != null && enabled.equalsIgnoreCase("true")) {
		// Init mail sesssion
		Properties props = new Properties();
		props.put("mail.host", smtpHost);
		Session session = Session.getDefaultInstance(props, null);

		// Create a message
		Message msg = new MimeMessage(session);

		// Set sender address.
		msg.setFrom(new InternetAddress("FSmsSoapMock@adnovum.ch"));

		// Set recipient address.
		InternetAddress[] addressTo = new InternetAddress[1];
		addressTo[0] = new InternetAddress(recipient);
		msg.setRecipients(Message.RecipientType.TO, addressTo);

		// Set the subject.
		msg.setSubject("FSmsSoapMock : MockService : SendSms" );

		// Set the content.
		StringBuilder buf = new StringBuilder();
		buf.append("Phone number: ").append(phoneNumber).append("\n\n");
		buf.append("SMS text    : ").append(smsText).append("\n");
		msg.setContent( buf.toString(), "text/plain");

		// Send the e-mail.
		Transport.send(msg);

		log.info("Confirmation e-mail sent.");
	}
	else {
		log.info("Sending of confirmation e-mail not enabled.");
	}	

	// Indicate success.
	success = true;
}
catch (Exception e) {
	log.error("Failed to send confirmation e-mail: ", e);

	// Indicate failure.
	success = false;
}

return success ? "Successful Call" : "Unsuccessful Call"

import java.io.File;
import java.io.FileInputStream;
import java.util.Properties;

import javax.activation.DataHandler;
import javax.activation.FileDataSource;
import javax.activation.MimetypesFileTypeMap;

import javax.mail.Message;
import javax.mail.Multipart;
import javax.mail.Session;
import javax.mail.Transport;
import javax.mail.internet.InternetAddress;
import javax.mail.internet.MimeBodyPart;
import javax.mail.internet.MimeMessage;
import javax.mail.internet.MimeMultipart;

static final String SIM_EXEC_DIRECTORY = ".";
static final String PROPERTY_DIRECTORY = "build/dist/etc/soapui/";
static final String PROPERTY_FILE_NAME = "soapui.properties";
static final String ENABLED_PROPERTY   = "mockup.email.enabled";
static final String RECIPIENT_PROPERTY = "mockup.email.recipient";
static final String SMTP_HOST_PROPERTY = "mockup.email.smtp.host";
static final String DEFAULT_SMTP_HOST  = "smtp-dev.adnovum.ch";

def groovyUtils = new com.eviware.soapui.support.GroovyUtils(context)
def xmlHolder   = groovyUtils.getXmlHolder(mockRequest.requestContent)
def faxNumber   = xmlHolder.getNodeValue("//*:argsNumber")
def fileName    = xmlHolder.getNodeValue("//*:argsFileName")

log.info("fax number: " + faxNumber)
log.info("file name : " + fileName)

boolean success = false;
try {
	// Get name of user who is running the application.
	Properties systemProperties = System.getProperties();
	String userName = systemProperties.getProperty("user.name");

	// Get configurable properties.
	String enabled = null;
	String smtpHost = null;
	String recipient = null;
	File propertyDir = new File(SIM_EXEC_DIRECTORY, PROPERTY_DIRECTORY);
	File propertyFile = new File(propertyDir, PROPERTY_FILE_NAME);
	try {
		Properties properties = new Properties();
		properties.load(new FileInputStream(propertyFile));
		enabled = properties.getProperty(ENABLED_PROPERTY);
		smtpHost = properties.getProperty(SMTP_HOST_PROPERTY);
		recipient = properties.getProperty(RECIPIENT_PROPERTY);
	}
	catch (Exception e) {
		log.error("Could not load properties file " + propertyFile.getAbsolutePath(), e);
	}
	if (smtpHost == null || smtpHost.equals("")) {
		smtpHost = DEFAULT_SMTP_HOST;
	}
	if (recipient == null || recipient.equals("")) {
		recipient = userName + "@adnovum.ch";
	}

	// If enabled, send e-mail confirmation of fax file.
	if (enabled != null && enabled.equalsIgnoreCase("true")) {
		// Get the file.
		File file = new File(fileName);

		// Init mail sesssion.
		Properties props = new Properties();
		props.put("mail.host", "smtp-dev.adnovum.ch");
		Session session = Session.getDefaultInstance(props, null);

		// Create a message.
		Message msg = new MimeMessage(session);

		// Set sender address.
		msg.setFrom(new InternetAddress("FFaxSoapMock@adnovum.ch"));

		// Set recipient address.
		InternetAddress[] addressTo = new InternetAddress[1];
		addressTo[0] = new InternetAddress(recipient);
		msg.setRecipients(Message.RecipientType.TO, addressTo);

		// Set the subject.
		msg.setSubject("FFaxSoapMock : MockService : SendFaxFile" );

		// Set the content.
		StringBuilder buf = new StringBuilder();
		buf.append("Fax number: ").append(faxNumber).append("\n\n");
		buf.append("File name : ").append(fileName).append("\n");
		if (!file.isFile()) {
		    buf.append("            (file not found)\n");
		}

		MimeBodyPart textBodyPart = new MimeBodyPart();
		textBodyPart.setText(buf.toString());

		// Add body text to e-mail.
		Multipart multipart = new MimeMultipart();
		multipart.addBodyPart(textBodyPart);

		if (file.isFile()) {
		    // Add missing MIME types to map.
		    MimetypesFileTypeMap fileTypeMap = new MimetypesFileTypeMap();
		    fileTypeMap.addMimeTypes("application/pdf pdf PDF");

		    // Create data source which recognizes file extensions.
		    FileDataSource dataSource = new FileDataSource(fileName);
		    dataSource.setFileTypeMap(fileTypeMap);
		    DataHandler dataHandler = new DataHandler(dataSource);

		    // Create MIME body part for file attachment.
		    MimeBodyPart fileBodyPart = new MimeBodyPart();
		    fileBodyPart.setDataHandler(dataHandler);
		    fileBodyPart.setFileName(file.getName());

		    // Add file attachment to e-mail.
		    multipart.addBodyPart(fileBodyPart);
		}
		msg.setContent(multipart);

		// Send the e-mail.
		Transport.send(msg);

		log.info("Confirmation e-mail sent.");
	}
	else {
		log.info("Sending of confirmation e-mail not enabled.");
	}	

	// Indicate success.
	success = true;
}
catch (Exception e) {
	log.error("Failed to send confirmation e-mail: ", e);

	// Indicate failure.
	success = false;
}

return success ? "Successful Call" : "Unsuccessful Call"

